import time

class RetryDispatcher:
    def __init__(self, max_attempts=3, base_delay=0.1, max_delay=1.0):
        # Validate configuration parameters
        if type(max_attempts) is not int or isinstance(max_attempts, bool):
            raise ValueError("max_attempts must be a non-boolean integer")
        if max_attempts <= 0:
            raise ValueError("max_attempts must be a positive integer")
        if not isinstance(base_delay, (int, float)) or isinstance(base_delay, bool):
            raise ValueError("base_delay must be a non-boolean number")
        if base_delay < 0:
            raise ValueError("base_delay cannot be negative")
        if not isinstance(max_delay, (int, float)) or isinstance(max_delay, bool):
            raise ValueError("max_delay must be a non-boolean number")
        if max_delay < 0:
            raise ValueError("max_delay cannot be negative")
        if max_delay < base_delay:
            raise ValueError("max_delay cannot be less than base_delay")

        self.max_attempts = max_attempts
        self.base_delay = float(base_delay)
        self.max_delay = float(max_delay)

    def calculate_backoff(self, attempt):
        # Validate attempt number
        if type(attempt) is not int or isinstance(attempt, bool):
            raise ValueError("attempt must be a non-boolean integer")
        if attempt <= 0:
            raise ValueError("attempt must be a positive integer")
        # Exponential backoff clamped to max_delay
        delay = self.base_delay * (2 ** (attempt - 1))
        return min(delay, self.max_delay)

    def execute(self, func, payload, dlq_sink):
        # Defensive argument validation
        if not callable(func):
            raise ValueError("func must be a callable")
        if not hasattr(dlq_sink, "send") or not callable(getattr(dlq_sink, "send")):
            raise ValueError("dlq_sink must have a callable 'send' method")

        attempts = 0
        last_err = None
        while attempts < self.max_attempts:
            attempts += 1
            try:
                return func(payload)
            except Exception as e:
                last_err = e
                # Immediate routing for non‑retryable errors
                if isinstance(e, NonRetryableError):
                    try:
                        dlq_sink.send(payload, e, attempts)
                    except Exception as dlq_err:
                        # Preserve original error context
                        raise RuntimeError("Failed to route to DLQ") from dlq_err
                    raise e
                # Retryable errors – decide whether to retry or exhaust
                if isinstance(e, RetryableError) and attempts < self.max_attempts:
                    # Apply exponential backoff before next attempt
                    delay = self.calculate_backoff(attempts)
                    time.sleep(delay)
                    continue
                # Exhausted retries or unexpected exception – route to DLQ
                try:
                    dlq_sink.send(payload, e, attempts)
                except Exception as dlq_err:
                    raise RuntimeError("Failed to route to DLQ") from dlq_err
                raise e
        # Should not reach here; raise the last captured error for safety
        raise last_err

