import time
from numbers import Number

class RetryDispatcher:
    """Dispatches a callable with retry semantics and dead‑letter routing.

    Parameters
    ----------
    max_attempts: int
        Maximum number of attempts (including the initial try). Must be a
        positive integer and not a boolean.
    base_delay: float
        Base delay in seconds for exponential backoff. Must be a positive
        number (int or float) and not a boolean.
    max_delay: float
        Upper bound for backoff delay. Must be a positive number, not a
        boolean, and greater than or equal to ``base_delay``.
    """

    def __init__(self, max_attempts=3, base_delay=0.1, max_delay=1.0):
        # ---- Parameter validation ----
        if type(max_attempts) is not int:
            raise ValueError("max_attempts must be an int (bools are not allowed)")
        if max_attempts <= 0:
            raise ValueError("max_attempts must be positive")
        if not isinstance(base_delay, Number) or isinstance(base_delay, bool):
            raise ValueError("base_delay must be a numeric type (int/float) and not bool")
        if base_delay <= 0:
            raise ValueError("base_delay must be positive")
        if not isinstance(max_delay, Number) or isinstance(max_delay, bool):
            raise ValueError("max_delay must be a numeric type (int/float) and not bool")
        if max_delay <= 0:
            raise ValueError("max_delay must be positive")
        if max_delay < base_delay:
            raise ValueError("max_delay cannot be less than base_delay")

        self.max_attempts = max_attempts
        self.base_delay = float(base_delay)
        self.max_delay = float(max_delay)

    def calculate_backoff(self, attempt: int) -> float:
        """Calculate exponential backoff delay for a given attempt.

        Parameters
        ----------
        attempt: int
            The current attempt number (1‑based). Must be a positive integer.
        """
        if type(attempt) is not int:
            raise ValueError("attempt must be an int (bools are not allowed)")
        if attempt <= 0:
            raise ValueError("attempt must be positive")
        delay = self.base_delay * (2 ** (attempt - 1))
        return min(delay, self.max_delay)

    def _validate_callable(self, func):
        if not callable(func):
            raise ValueError("func must be callable")

    def _validate_dlq_sink(self, dlq_sink):
        if not hasattr(dlq_sink, "send") or not callable(getattr(dlq_sink, "send")):
            raise ValueError("dlq_sink must provide a callable 'send' method")

    def execute(self, func, payload, dlq_sink):
        """Execute *func* with *payload* respecting retry policy.

        - ``NonRetryableError`` triggers immediate DLQ routing.
        - ``RetryableError`` (or any other exception) is retried up to
          ``max_attempts`` with exponential backoff.
        - After exhausting retries, the last error is sent to the DLQ.
        """
        # ---- Input validation ----
        self._validate_callable(func)
        self._validate_dlq_sink(dlq_sink)

        attempts = 0
        last_err = None
        while attempts < self.max_attempts:
            attempts += 1
            try:
                return func(payload)
            except NonRetryableError as nre:
                # Immediate dead‑letter routing
                try:
                    dlq_sink.send(payload, nre, attempts)
                except Exception as dlq_err:
                    # Propagate DLQ failure – no partial state should remain.
                    raise dlq_err
                raise nre
            except Exception as e:
                last_err = e
                if attempts >= self.max_attempts:
                    break
                # Backoff before next attempt
                delay = self.calculate_backoff(attempts)
                try:
                    time.sleep(delay)
                except Exception:
                    # If sleep fails, abort with the original exception.
                    raise last_err
                # Continue loop for next retry
        # Exhausted retries – route to DLQ with failure metadata
        try:
            dlq_sink.send(payload, last_err, attempts)
        except Exception as dlq_err:
            raise dlq_err
        raise last_err
